#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll extendedGcd(ll a, ll b, ll& x, ll& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }

    ll x1, y1;
    ll g = extendedGcd(b, a % b, x1, y1);
    x = y1;
    y = static_cast<ll>((i128)x1 - (i128)(a / b) * y1);
    return g;
}

void solve() {
    ll a, b, c;
    cin >> a >> b >> c;

    if (c < 0 || a < 0 || b < 0) {
        cout << "No\n";
        return;
    }

    if (a == 0 && b == 0) {
        cout << (c == 0 ? "Yes\n" : "No\n");
        return;
    }

    if (a == 0) {
        cout << (c % b == 0 ? "Yes\n" : "No\n");
        return;
    }

    if (b == 0) {
        cout << (c % a == 0 ? "Yes\n" : "No\n");
        return;
    }

    ll g = std::gcd(a, b);
    if (c % g != 0) {
        cout << "No\n";
        return;
    }

    a /= g;
    b /= g;
    c /= g;

    if (b == 1) {
        cout << "Yes\n";
        return;
    }

    ll inverse, unused;
    extendedGcd(a, b, inverse, unused);
    inverse = (inverse % b + b) % b;

    ll x = static_cast<ll>((i128)(c % b) * inverse % b);
    cout << ((i128)a * x <= c ? "Yes\n" : "No\n");
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

