bool hasNonNegativeSolution(ll a, ll b, ll c) {
    if (c < 0 || a < 0 || b < 0) return false;

    if (a == 0 && b == 0) return c == 0;
    if (a == 0) return c % b == 0;
    if (b == 0) return c % a == 0;

    ll g = std::gcd(a, b);
    if (c % g != 0) return false;

    ll aa = a / g;
    ll bb = b / g;
    ll cc = c / g;

    if (bb == 1) return true;

    ll x, y;
    extendedGcd(aa, bb, x, y);

    ll inverse = (x % bb + bb) % bb;
    ll x0 = static_cast<ll>(
        (static_cast<i128>(cc % bb) * inverse) % bb
    );

    return static_cast<i128>(aa) * x0 <= cc;
}

